import{_ as i,l as n,o as e,c as l,v as r,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"二进制加固与混淆","description":"","frontmatter":{"title":"二进制加固与混淆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/binary-hardening-obfuscation.md","filePath":"cs/binary-hardening-obfuscation.md","lastUpdated":1789023840000}'),c={name:"cs/binary-hardening-obfuscation.md"};function E(_,a,b,u,A,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="二进制加固与混淆" tabindex="-1">二进制加固与混淆 <a class="header-anchor" href="#二进制加固与混淆" aria-label="Permalink to &quot;二进制加固与混淆&quot;">​</a></h1><div class="epigraph"><p>加固是让控制流劫持变贵：NX、ASLR、CFI、RELRO。混淆是让分析变贵：控制流平坦、字符串加密。前者是默认应开的合同；后者不能当秘密算法，也常被恶意软件用来拖分析员。</p><footer>—— 据 Szekeres SoK 的缓解谱；Collberg 对混淆的限度；对照 GNU 硬化和 LLVM CFI</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/rootkits">rootkit</a>说明特权下检测难。缺口是<strong>用户态二进制自己的默认编译选项</strong>与「靠混淆藏逻辑」的幻想。本课分清加固与混淆，不教反调试对抗。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发行构建若关 PIE/NX，利用课的开口回来。混淆不增加密码学假设，只增加逆向时间；密钥仍在端上。缺口是发布清单：该开的缓解、不该指望的秘密。</p><h3 id="恶意软件也混淆" tabindex="-1">恶意软件也混淆 <a class="header-anchor" href="#恶意软件也混淆" aria-label="Permalink to &quot;恶意软件也混淆&quot;">​</a></h3><p>分析员要用沙箱与内存转储，而不是假设混淆等于不可分析。</p><p><span class="marginnote">Collberg：混淆没有密码学意义上的一般不可破解。本课禁止写商业软件保护绕过教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列加固开关（PIE、Fortify、CFI）。对照混淆：可作知识产权延迟，不可作唯一控制。软件安全单元封口，下一单元 Web。</p>',12)),(e(),s(p,null,{default:t(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HARD%5B%22NX%20ASLR%20CFI%20RELRO%22%5D%20--%3E%20COST%5B%22%E6%8F%90%E9%AB%98%E5%88%A9%E7%94%A8%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20OBF%5B%22%E6%B7%B7%E6%B7%86%22%5D%20--%3E%20TIME%5B%22%E6%8F%90%E9%AB%98%E5%88%86%E6%9E%90%E6%97%B6%E9%97%B4%22%5D%0A%20%20OBF%20-.-%3E%7C%22%E9%9D%9E%E5%AF%86%E7%A0%81%E5%AD%A6%E4%BF%9D%E5%AF%86%22%7C%20LIM%5B%22%E5%AF%86%E9%92%A5%E4%BB%8D%E5%9C%A8%E7%AB%AF%E4%B8%8A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现与工程课序结束于「如何发行」。Web 单元从 XSS 起：解释器在浏览器里，洞的形状换成脚本注入。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给脱壳步骤。下一单元第一课 XSS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rootkit 在特权层；用户态仍要开加固。</li><li>混淆拖时间，不是 Shannon 保密。</li><li>发行清单对准缓解，不对准秘密算法。</li><li>下一单元：XSS。</li><li>出处：Szekeres et al.；Collberg；GNU hardening / LLVM CFI。</li></ul>',8))])}const S=i(c,[["render",E]]);export{m as __pageData,S as default};
